/*
Plans are defined here:
https://github.com/github/github/blob/08fbc277887194aa209926bf266f9d877b22cf0e/packages/billing/app/models/github/plan.rb#L28

And enterprise cloud plans have a name of "business_plus"
https://github.com/github/github/blob/08fbc277887194aa209926bf266f9d877b22cf0e/config/plans.yml#L201
*/
export function isEnterpriseCloudPlan(plan: string): boolean {
  const normalizedPlan = plan.toLowerCase()
  return normalizedPlan === 'business_plus'
}

