import {MachineSpecArchitecture} from './machine-spec'

export const PlatformOsType = {
  Linux: 'Linux',
  MacOS: 'MacOS',
  Windows: 'Windows',
} as const

export type PlatformOsType = (typeof PlatformOsType)[keyof typeof PlatformOsType]

export const platformOptions = [
  {
    displayName: 'Linux x64',
    id: 'linux-x64',
    osType: PlatformOsType.Linux,
    architecture: MachineSpecArchitecture.x64,
  },
  {
    displayName: 'Linux ARM64',
    id: 'linux-arm64',
    osType: PlatformOsType.Linux,
    architecture: MachineSpecArchitecture.ARM64,
  },
  {
    displayName: 'Windows x64',
    id: 'win-x64',
    osType: PlatformOsType.Windows,
    architecture: MachineSpecArchitecture.x64,
  },
  {
    displayName: 'Windows ARM64',
    id: 'win-arm64',
    osType: PlatformOsType.Windows,
    architecture: MachineSpecArchitecture.ARM64,
  },
  {
    displayName: 'macOS x64',
    id: 'macos-x64',
    osType: PlatformOsType.MacOS,
    architecture: MachineSpecArchitecture.x64,
  },
  {
    displayName: 'macOS ARM64',
    id: 'macos-arm64',
    osType: PlatformOsType.MacOS,
    architecture: MachineSpecArchitecture.ARM64,
  },
  {
    displayName: 'Upload custom image',
    id: 'custom',
    osType: PlatformOsType.Linux,
    architecture: MachineSpecArchitecture.x64,
  },
] as const

// `Platform` is a type that can be any of the objects in the `platformOptions` array
export type Platform = (typeof platformOptions)[number]
export type PlatformId = Platform['id']

/**
 * Returns available platforms based on whether macOS runner groups are enabled for the current owner.
 */
export function getAvailablePlatforms(isMacosInRunnerGroupsEnabled: boolean): Platform[] {
  if (isMacosInRunnerGroupsEnabled) {
    return [...platformOptions]
  }

  return platformOptions.filter(p => p.osType !== PlatformOsType.MacOS)
}

export function platformToOsType(platformInput: PlatformId): PlatformOsType {
  return platformOptions.find(p => p.id === platformInput)?.osType ?? PlatformOsType.Linux
}

export function findPlatformById(platformId: string): Platform {
  return platformOptions.find(p => p.id === platformId) as Platform
}
