import {Button, FormControl} from '@primer/react'
import {clsx} from 'clsx'
import {cloneElement, type ReactElement} from 'react'

import styles from './FieldProgressionField.module.css'
import type {Platform} from '../../../types/platform'
import type {MachineSpec} from '../../../types/machine-spec'

// Custom editor components are expected to implement this interface
export interface FieldProgressionFieldEditComponentProps<T> {
  value: T | null
  setValue: (value: T | null) => void
  onSave?: () => void
}

interface FieldProgressionFieldEditComponent extends ReactElement {
  props: FieldProgressionFieldEditComponentProps<MachineSpec | Platform | string>
}

export type FieldProgressionFieldProps = {
  name: string
  displayValue: string | null
  isActive?: boolean
  index?: number
  onEditClick?: () => void
  onSave?: () => void
  error?: boolean
  editComponent: FieldProgressionFieldEditComponent
}

export default function FieldProgressionField({
  name,
  displayValue,
  isActive,
  index,
  onEditClick,
  onSave,
  editComponent,
  error,
}: FieldProgressionFieldProps) {
  // FieldProgression will pass an index prop to its editComponent
  if (index === undefined) {
    throw new Error('FieldProgressionField must be rendered as a child of a FieldProgression component')
  }

  const hasValue = displayValue !== null
  const validationId = `field-progression-field-validation-${index}`

  // eslint-disable-next-line @eslint-react/no-clone-element
  const activeField = cloneElement(editComponent, {onSave})
  const inactiveField = (
    <div className={styles.inactiveField}>
      {hasValue ? (
        <span>{displayValue}</span>
      ) : (
        <span className={styles.mutedText}>{`No ${name.toLowerCase()} selected`}</span>
      )}
    </div>
  )

  return (
    <>
      <div
        data-testid={`field-progression-field-${index}`}
        className={clsx('d-flex flex-items-center', styles.fieldContainer, error && styles.fieldContainerError)}
        aria-describedby={validationId}
      >
        <FormControl className={styles.formControl}>
          <FormControl.Label className={styles.formControlLabel}>{name}</FormControl.Label>
          <div className={styles.fieldContent}>{isActive ? activeField : inactiveField}</div>
        </FormControl>
        {!isActive && hasValue && (
          <Button
            className={styles.editButton}
            variant="invisible"
            onClick={onEditClick}
            data-testid={`field-progression-field-edit-button-${index}`}
          >
            Edit
          </Button>
        )}
      </div>

      {error && (
        <FormControl.Validation
          variant="error"
          className={styles.validationMessage}
          id={validationId}
        >{`${name} is required.`}</FormControl.Validation>
      )}
    </>
  )
}
